        try_files $uri $uri/ =404;
    }'''
ins='''    location /owner/ {
        auth_basic "AYET Owner";
        auth_basic_user_file /etc/nginx/.ayet_htpasswd;
        try_files $uri $uri/ =404;
    }

    location / {
        try_files $uri $uri/ =404;
    }'''
if "location /owner/" in s:
    print("owner auth already present")
elif target in s:
    s=s.replace(target,ins,1); open(f,"w").write(s); print("inserted /owner/ auth into HTTPS server")
else:
